WHERE p.user_id = #{userId}
AND c.start_date > #{today}

    AND c.start_date <= #{today} AND c.end_date >= #{today}

AND c.end_date < #{today}

mapper.select:
SELECT c.id, c.title, c.start_date, c.end_date, c.goal_type, c.goal_value
FROM challenge_participants p
JOIN challenges c ON c.id = p.challenge_id
WHERE p.user_id = #{userId}
  AND p.completed_at IS NULL
  AND c.goal_type = #{goalType}
  AND c.start_date <= #{date} AND c.end_date >= #{date}
ORDER BY c.id
FOR UPDATE OF p

SELECT COUNT(*) FROM review_plans
WHERE user_id = #{userId} AND status = 'DONE'
  AND done_at >= #{from} AND done_at < #{until}

SELECT COUNT(DISTINCT quiz_id, DATE(created_at)) FROM quiz_attempts
WHERE user_id = #{userId}
  AND created_at >= #{from} AND created_at < #{until}

SELECT COUNT(*) FROM analyses
WHERE user_id = #{userId} AND status = 'DONE'
  AND created_at >= #{from} AND created_at < #{until}

mapper.update:
UPDATE challenge_participants
SET progress = #{progress}, completed_at = #{completedAt}
WHERE challenge_id = #{challengeId} AND user_id = #{userId} AND completed_at IS NULL
